INSERT INTO sql_questions (id, title, category, difficulty, question_text, hints, solution_sql, explanation) VALUES
('a1b2c3d4-0000-0000-0000-000000000001', 'Combine Two Tables', 'Joins', 'Easy', 'Write a solution to report the first name, last name, city, and state of each person in the Person table. If the address of a personId is not present in the Address table, report null instead.', 'Use a LEFT JOIN to include people even if they don''t have an address.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000002', 'Second Highest Salary', 'Aggregations', 'Medium', 'Write a solution to find the second highest distinct salary from the Employee table. If there is no second highest salary, return null.', 'Consider using the LIMIT and OFFSET clauses.
How do you handle the case where there is only one distinct salary?', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000003', 'Nth Highest Salary', 'Functions', 'Medium', 'Write a solution to find the nth highest distinct salary from the Employee table. If there is no nth highest salary, return null.', 'You need to declare a function.
Remember that OFFSET takes a variable but you might need to compute N-1 first.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000004', 'Rank Scores', 'Window Functions', 'Medium', 'Write a solution to find the rank of the scores. The ranking should be calculated according to the rules: descending order, ties share same rank, next rank is consecutive.', 'Look into window functions, specifically DENSE_RANK().', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000005', 'Consecutive Numbers', 'Window Functions', 'Medium', 'Find all numbers that appear at least three times consecutively.', 'You can join the table to itself twice, or use LEAD/LAG window functions.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000006', 'Employees Earning More Than Their Managers', 'Joins', 'Easy', 'Write a solution to find the employees who earn more than their managers.', 'Join the Employee table with itself where e1.managerId = e2.id.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000007', 'Duplicate Emails', 'Aggregations', 'Easy', 'Write a solution to report all the duplicate emails. Note that it''s guaranteed that the email field is not NULL.', 'Group by email and use HAVING count(email) > 1.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000008', 'Customers Who Never Order', 'Filtering', 'Easy', 'Write a solution to find all customers who never order anything.', 'LEFT JOIN Customers with Orders and filter where Order.id IS NULL.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000009', 'Department Highest Salary', 'Joins', 'Medium', 'Write a solution to find employees who have the highest salary in each of the departments.', 'Find the max salary per department first, then join with Employee.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000010', 'Department Top Three Salaries', 'Window Functions', 'Hard', 'Write a solution to find the employees who are high earners in each of the departments. A high earner in a department is an employee who has a salary in the top three unique salaries for that department.', 'Use DENSE_RANK() OVER (PARTITION BY departmentId ORDER BY salary DESC).', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000011', 'Delete Duplicate Emails', 'Data Manipulation', 'Easy', 'Write a solution to delete all duplicate emails, keeping only one unique email with the smallest id. Execute a DELETE statement.', 'DELETE p1 FROM Person p1, Person p2 WHERE p1.Email = p2.Email AND p1.Id > p2.Id', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000012', 'Rising Temperature', 'Joins', 'Easy', 'Write a solution to find all dates'' Id with higher temperatures compared to its previous dates (yesterday).', 'Use DATEDIFF() to compare the dates in a self join.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000013', 'Trips and Users', 'Aggregations', 'Hard', 'Find the cancellation rate of requests with unbanned users each day between ''2013-10-01'' and ''2013-10-03''. Round Cancellation Rate to two decimal points.', 'Calculate total unbanned trips and cancelled unbanned trips per day.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000014', 'Game Play Analysis I', 'Aggregations', 'Easy', 'Write a solution to report the first login date for each player.', 'Use the MIN() function on the event_date grouped by player_id.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000015', 'Game Play Analysis IV', 'Window Functions', 'Medium', 'Write a solution to report the fraction of players that logged in again on the day after the day they first logged in, rounded to 2 decimal places.', 'Find the first login date for each player, then check if they logged in on first_login + 1.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000016', 'Managers with at Least 5 Direct Reports', 'Aggregations', 'Medium', 'Write a solution to find managers with at least five direct reports.', 'Group by managerId and use HAVING count >= 5, then join back to get the manager''s name.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000017', 'Find Customer Referee', 'Filtering', 'Easy', 'Write a solution to find the names of the customer that are not referred by the customer with id = 2.', 'Remember to account for customers whose referee_id is NULL.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000018', 'Customer Placing the Largest Number of Orders', 'Aggregations', 'Easy', 'Write a solution to find the customer_number for the customer who has placed the largest number of orders.', 'Group by customer_number, order by count descending, and limit to 1.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000019', 'Big Countries', 'Filtering', 'Easy', 'A country is big if it has an area of at least 3 million km2, or it has a population of at least 25 million. Find the name, population, and area of the big countries.', 'Use a simple WHERE clause with an OR condition.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000020', 'Classes More Than 5 Students', 'Aggregations', 'Easy', 'Write a solution to find all the classes that have at least five students.', 'Group by class and count the students.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000021', 'Human Traffic of Stadium', 'Window Functions', 'Hard', 'Write a solution to display the records with three or more rows with consecutive id''s, and the number of people is greater than or equal to 100 for each.', 'Find groups of consecutive IDs where people >= 100 using id - ROW_NUMBER().', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000022', 'Exchange Seats', 'Functions', 'Medium', 'Write a solution to swap the seat id of every two consecutive students. If the number of students is odd, the id of the last student is not swapped.', 'Use CASE WHEN id % 2 = 1 THEN id + 1 ELSE id - 1 END.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000023', 'Swap Salary', 'Data Manipulation', 'Easy', 'Write a solution to swap all ''f'' and ''m'' values with a single update statement and no intermediate temporary tables.', 'Use an UPDATE statement with a CASE expression.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000024', 'Actors and Directors Who Cooperated At Least Three Times', 'Aggregations', 'Easy', 'Write a solution to find all the pairs (actor_id, director_id) where the actor has cooperated with the director at least three times.', 'Group by actor_id and director_id and count the rows.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000025', 'Sales Person', 'Joins', 'Easy', 'Write a solution to find the names of all the salespersons who did not have any orders related to the company with the name ''RED''.', 'Find all sales_id that have orders with ''RED'', then select salespersons not in that list.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000026', 'Triangle Judgement', 'Functions', 'Easy', 'Report for every three line segments whether they can form a triangle.', 'The sum of any two sides must be strictly greater than the third side.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000027', 'Tree Node', 'Functions', 'Medium', 'Each node in the tree can be one of three types: Root, Leaf, or Inner. Write a solution to report the type of each node in the tree.', 'If p_id is null, it''s Root. If id is in p_id, it''s Inner. Else Leaf.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000028', 'Not Boring Movies', 'Filtering', 'Easy', 'Write a solution to report the movies with an odd-numbered ID and a description that is not ''boring''.', 'Use id % 2 = 1 or MOD(id, 2) = 1 to check for odd IDs.', NULL, NULL),
('a1b2c3d4-0000-0000-0000-000000000029', 'Capital Gain/Loss', 'Aggregations', 'Medium', 'Write a solution to report the Capital gain/loss for each stock. The Capital gain/loss of a stock is the total gain or loss after buying and selling the stock one or many times.', 'Use SUM with CASE WHEN operation = ''Buy'' THEN -price ELSE price END.', NULL, NULL),
